const order = [];
const microQ = [];
const queueMicro = (fn) => microQ.push(fn); // models the engine's microtask queue
order.push('sync-1');
queueMicro(() => order.push('micro-A'));
order.push('sync-2');
queueMicro(() => order.push('micro-B'));
order.push('sync-3');
// The synchronous task runs to completion first; only THEN does the engine
// drain the microtask queue (FIFO), before control returns to the host.
while (microQ.length) microQ.shift()();
console.log(order.join(' '));

tasks.starter:
function run(initialMacro){
  const macroQ = [...initialMacro];
  const microQ = [];
  const order = [];
  const ctx = {
    log: (m) => order.push(m),
    queueMicro: (fn) => microQ.push(fn),
    queueMacro: (fn) => macroQ.push(fn),
  };
  while (macroQ.length) {
    const task = macroQ.shift();
    task(ctx);
    // drain only ONE microtask per macrotask, then loop
    if (microQ.length) microQ.shift()(ctx);
  }
  return order;
}

tasks.verify:
const order = run([
  (ctx) => {
    ctx.log('macro-1');
    ctx.queueMicro((c) => { c.log('micro-A'); c.queueMicro((c2) => c2.log('micro-B')); });
    ctx.queueMacro((c) => c.log('macro-2'));
  },
]);
const ok = order.join(',') === 'macro-1,micro-A,micro-B,macro-2';
console.log(ok ? 'PASS' : 'FAIL ' + order.join(','));
